import re
from auto_config.generator.vcu.managed_objects.managed_object import ManagedObject


class IprtParamsGenerator(ManagedObject):

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.iprt_ent = self.enb_ent_config['static_routes'] if 'static_routes' in self.enb_ent_config else {}

    def _prepare_section_content(self, execution_config, *args, **kwargs):
        srch = re.search(r"TNL-(\d+)/", self.dist_name)
        tnl_num = srch.group(1)
        iprt_entries = []
        if tnl_num == '1' and 'oam' in self.iprt_ent:
            iprt_entries = self.iprt_ent['oam']
        elif tnl_num == '2' and 'control_plane' in self.iprt_ent:
            iprt_entries = self.iprt_ent['control_plane']
        elif tnl_num == '3' and 'user_plane' in self.iprt_ent:
            iprt_entries = self.iprt_ent['user_plane']

        if iprt_entries:
            iprt_params = []
            for iprt_entry in iprt_entries:
                iprt_params.append({
                    'destIpAddr': iprt_entry['dest_ip_addr'],
                    'destinationIpPrefixLength': iprt_entry['dest_ip_mask'],
                    'gateway': iprt_entry['gateway'],

                })
            self.set_struct_parameter('staticRoutes', iprt_params)
